def backlash(u, k, b, nper=2):
    per = len(u)
    cur = k * (u[0] - b)
    out = []
    for p in range(nper):
        for i in range(per):
            rising = u[i] > u[i - 1] if i > 0 else True
            if rising:
                cur = max(cur, k * (u[i] - b))
            else:
                cur = min(cur, k * (u[i] + b))
            out.append(cur)
    return np.array(out[-per:])


def df_num(f, A, N=40000):
    th = np.linspace(0, 2 * np.pi, N, endpoint=False)
    y = f(A * np.sin(th))
    b1 = (2.0 / N) * np.sum(y * np.sin(th))
    a1 = (2.0 / N) * np.sum(y * np.cos(th))
    return (b1 + 1j * a1) / A


def N_sat(A, k=1.0, a=1.0):
    if A <= a:
        return k + 0j
    al = np.arcsin(a / A)
    return (2 * k / np.pi) * (al + np.sin(al) * np.cos(al)) + 0j


def N_dz(A, k=1.0, a=0.3):
    if A <= a:
        return 0j
    al = np.arcsin(a / A)
    return (2 * k / np.pi) * (np.pi / 2 - al - np.sin(al) * np.cos(al)) + 0j


def N_relay(A, M=1.0):
    return 4 * M / (np.pi * A) + 0j


def N_relay_h(A, M=1.0, h=0.2):
    if A <= h:
        return 0j
    return (4 * M / (np.pi * A)) * (np.sqrt(1 - (h / A) ** 2) - 1j * (h / A))


def N_bl(A, k=1.0, b=0.3):
    if A <= b:
        return 0j
    be = np.arcsin(1 - 2 * b / A)
    return (k / np.pi) * (np.pi / 2 + be + np.sin(be) * np.cos(be)
                          - 4j * (b / A) * (1 - b / A))

import numpy as np
import matplotlib.pyplot as plt
from scipy.optimize import brentq, fsolve
