def hrelay(M, h):
    st = {'s': -M}

    def f(e):
        if e > h:
            st['s'] = M
        elif e < -h:
            st['s'] = -M
        return st['s']
    return f


def N_rh(A, M=1.0, h=0.2):
    if A <= h:
        return 0j
    return (4 * M / (np.pi * A)) * (np.sqrt(1 - (h / A) ** 2) - 1j * (h / A))


def N_sat(A, k=1.0, a=1.0):
    if A <= a:
        return k + 0j
    al = np.arcsin(a / A)
    return (2 * k / np.pi) * (al + np.sin(al) * np.cos(al)) + 0j


def leak(G, w0, nmax=9):
    return sum(abs(G(n * w0)) / n for n in range(3, nmax + 1, 2)) / abs(G(w0))


def sim(f, T, dt, K, Tc, x0, order):
    x = np.array(x0, float)
    n = int(round(T / dt))
    ts = np.empty(n)
    es = np.empty(n)
    sw = 0
    ulast = None
    for k in range(n):
        e = -x[0]
        u = f(e)
        if ulast is not None and u != ulast:
            sw += 1
        ulast = u
        ts[k] = k * dt
        es[k] = e
        if order == 3:
            x[2] += dt * (-(1 + 1 / Tc) * x[2] - (1 / Tc) * x[1] + (K / Tc) * u)
            x[1] += dt * x[2]
            x[0] += dt * x[1]
        else:
            x[1] += dt * (-x[1] + K * u)
            x[0] += dt * x[1]
    return ts, es, sw


def rise_crossings(ts, sig, t_from, dt):
    m = np.where((sig[:-1] < 0) & (sig[1:] >= 0) & (ts[1:] >= t_from))[0]
    return [ts[i] + dt * (-sig[i]) / (sig[i + 1] - sig[i]) for i in m]


def measure(ts, sig, t_from, dt):
    m = ts >= t_from
    t, s = ts[m], sig[m]
    zc = [t[i - 1] + dt * (-s[i - 1]) / (s[i] - s[i - 1])
          for i in range(1, len(s)) if s[i - 1] < 0 <= s[i]]
    zc = np.array(zc)
    if len(zc) < 4:
        return None
    per = float(np.mean(np.diff(zc)))
    w = 2 * np.pi / per
    kk = len(zc) // 2
    ta, tb = zc[kk], zc[-1]
    mm = (t >= ta) & (t <= tb)
    tt, ss = t[mm], s[mm]
    A1 = 2 * np.trapezoid(ss * np.sin(w * (tt - ta)), tt) / (tb - ta)
    A2 = 2 * np.trapezoid(ss * np.cos(w * (tt - ta)), tt) / (tb - ta)
    amp = float(np.hypot(A1, A2))
    harm = [float(np.hypot(2 * np.trapezoid(ss * np.sin(nh * w * (tt - ta)), tt) / (tb - ta),
                           2 * np.trapezoid(ss * np.cos(nh * w * (tt - ta)), tt) / (tb - ta)))
            for nh in range(2, 8)]
    return dict(per=per, w=w, amp=amp, thd=float(np.sqrt(np.sum(np.array(harm) ** 2)) / amp))
